     **/
    @IsObject()
    @IsOptional()
    public metadata: Record<string, string>;
}
import { Point } from '@influxdata/influxdb-client';
import { MeasurementInfluxDbModel } from '../../influx/entities/measurementInfluxDbModel.interface';
import { InfluxService } from '../../influx/influx.service';
export enum ValidMeasurementTypes {
    int = 'int',
    float = 'float',
}

export abstract class MeasurementFormat {
    dimensionId?: string;
    applicationId?: string;
    serviceId?: string;
    timeStamp?: string;
    recordValue: number;
    businessID: string;
    metadata: Record<string, string>;
    _measurement: string;
    static getPointForm(measurement: MeasurementFormat, influxService: InfluxService): Point {
        const point = influxService.getPoint(measurement._measurement);
        point.timestamp(new Date(measurement.timeStamp));
        point.tag('applicationId', measurement.applicationId);
        point.tag('dimensionId', measurement.dimensionId);
        point.tag('serviceId', measurement.serviceId);
        point.tag('businessID', measurement.businessID);
        point.floatField('recordValue', measurement.recordValue);
        if (measurement?.metadata) {
            Object.keys(measurement.metadata).forEach((key) => {
                point.tag(`metadata_${key}`, measurement.metadata[key]);
            });
        }
        return point;
    }
    static toEntity(dbModel: MeasurementInfluxDbModel): MeasurementFormat {
        const measurementInput: MeasurementFormat = {
            timeStamp: dbModel._time,
            dimensionId: dbModel.dimensionId,
            applicationId: dbModel.applicationId,
            recordValue: dbModel._value,
            metadata: {},
            _measurement: dbModel._measurement,
            businessID: dbModel.businessID,
        };
        Object.keys(dbModel).forEach((key) => {
            if (key.startsWith('metadata_') && dbModel[key]) {
                // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                // @ts-ignore
                measurementInput.metadata[key.replace('metadata_', '')] = dbModel[key];
            }
        });
        return measurementInput;
    }
}
import { InfluxService } from '../../influx/influx.service';
import { UsageEntity } from '../../usage/entities/usage.entity';
import { StandardMeasurementEntity } from './standardMeasurement.entity';

export enum PreProcessorMeasurementType {
    AGENT = 'AGENT',
}

// Take in a raw data value which doesn't have serviceId, and or DimesnionId plus additional metadata
// Attach meatadata to the raw data value creating a standard measurement
// Publish the standard measurement to the standard measurement topic
// Contains a constructor to create the pre-processing entity, and then a method to process the raw data value doing the above steps.
export class StandardMeasurementPreProcessorEntity {
    // The raw data value
    public rawDataValue: string;
    // The businessID
    public businessID: string;
    // ENUM of the type of measurement
    public measurementType: PreProcessorMeasurementType;
    // metadata as a JSON object keys are the metadata names values are strings
    public metadata: Record<string, string>;
    // Optional Timestamp, if not provided will be set to the current time
    public timeStamp?: string;

    constructor(
        rawDataValue: string,
        businessID: string,
        measurementType: PreProcessorMeasurementType,
        metadata: Record<string, string>,
        timeStamp?: string
    ) {
        this.rawDataValue = rawDataValue;
        this.businessID = businessID;
        this.measurementType = measurementType;
        this.metadata = metadata;
        if (timeStamp) {
            this.timeStamp = timeStamp;
        } else {
            this.timeStamp = new Date().toISOString();
        }
    }
    static async createStandardMeasurement(
        preprocessed: StandardMeasurementPreProcessorEntity,
        uniqueInfrastructureId: string,
        influxService: InfluxService
    ) {
        let dimensionId;
        let serviceId;
        let applicationId;
        if (preprocessed.measurementType === PreProcessorMeasurementType.AGENT) {
            const startTime = new Date('January 1, 1970 00:00:00');
            const endTime = new Date();
            // get the dimensionId, and serviceId from Influx
            const data = await influxService.getLatestPodLabelsByID({
                podId: uniqueInfrastructureId,
                businessID: preprocessed.businessID,
                startTime: startTime.toISOString(),
                endTime: endTime.toISOString(),
            });
            if (data.length > 0) {
                const [{ label_enterprise_application_id, label_enterprise_dimension_id, label_enterprise_service_id }] = data;
                dimensionId = label_enterprise_dimension_id;
                serviceId = label_enterprise_service_id;
                applicationId = label_enterprise_application_id;
            } else {
                return { message: 'No labels found' };
            }
        }
        //
        const standardMeasurement = new StandardMeasurementEntity({
            businessID: preprocessed.businessID,
            recordValue: Number(preprocessed.rawDataValue),
            metadata: preprocessed.metadata,
            _measurement: UsageEntity._measurement,
            timeStamp: preprocessed.timeStamp,
            dimensionId,
            serviceId,
            applicationId,
        });
        StandardMeasurementEntity.publish(standardMeasurement);
    }
}

