export class DatastoreAccessInformation {
    private static readonly logger = new Logger(DatastoreAccessInformation.name);

    /**
     * The default region used for the ingestion and DLQ datastores when none is provided.
     */
    public static readonly defaultRegion = 'us-east-1';

    /**
     * The datastore platform enterprise ingests usage records from. Optional, default is `s3`.
     *
     */
    @Matches(
        `^${Object.values(SupportedDatastores)
            .filter((v) => typeof v !== 'number')
            .join('|')}$`,
        'i'
    )
    @IsOptional()
    @ApiProperty({
        enum: SupportedDatastores,
        isArray: false,
        required: false,
        examples: ['s3'],
    })
    public platform?: SupportedDatastores;

    /**
     * The unique ID of the cloud account which owns the datastore usage records are produced from. Required.
     * This is the account which is trusted to assume the generated ingestion IAM role.
     * @example "623673123435"
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({ example: '623673123435' })
    public accountId: string;

    /**
     * The region of the ingestion and DLQ datastores. Optional, default is `us-east-1`.
     * @example "us-east-1"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, example: 'us-east-1' })
    public region?: string;

    /**
     * READ ONLY. The IAM role generated by enterprise which the account identified by `accountId` can assume to
     * deliver usage records to enterprise, and read failed records from the DLQ.
     * @example "arn:aws:iam::647662420899:role/datastore-myBusiness-de388932-a7e1-11ed-afa1-0242ac120002"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, readOnly: true })
    public iamRoleArn?: string;

    /**
     * READ ONLY. The external ID which must be presented when assuming `iamRoleArn`.
     * @example "de388932-a7e1-11ed-afa1-0242ac120002"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, readOnly: true })
    public externalId?: string;

    /**
     * READ ONLY. The location usage records are delivered to.
     * @example "s3://enterprise-usage-record-dump-bucket/myBusiness"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, readOnly: true })
    public ingestion?: string;

    /**
     * READ ONLY. The location records which enterprise failed to process are delivered to.
     * @example "s3://enterprise-usage-record-dlq-bucket/myBusiness"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, readOnly: true })
    public dlq?: string;

    @ApiHideProperty()
    @IsOptional()
    public businessID?: string;

    @ApiHideProperty()
    @IsOptional()
    public measurementId?: string;

    constructor(datastoreAccessInformation: DatastoreAccessInformation) {
        if (datastoreAccessInformation) {
            const {
                platform,
                accountId,
                region,
                iamRoleArn,
                externalId,
                ingestion,
                dlq,
                businessID,
                measurementId,
                // Support the legacy names of the same information
                datastoreType,
                cloudId,
            } = datastoreAccessInformation as DatastoreAccessInformation & {
                datastoreType?: SupportedDatastores;
                cloudId?: string;
            };
            this.platform = (platform ? platform : datastoreType ? datastoreType : SupportedDatastores.s3)
                .toString()
                .toLowerCase() as SupportedDatastores;
            this.accountId = accountId ? accountId : cloudId;
            this.region = region ? region : DatastoreAccessInformation.defaultRegion;
            this.businessID = businessID;
            this.measurementId = measurementId;
            if (iamRoleArn) {
                this.iamRoleArn = iamRoleArn;
            }
            if (externalId) {
                this.externalId = externalId;
            }
            this.ingestion = ingestion ? ingestion : DatastoreAccessInformation.getIngestionLocation(businessID);
            this.dlq = dlq ? dlq : DatastoreAccessInformation.getDLQLocation(businessID);
        }
    }

    /**
     * The name of the IAM role, and the policy attached to it, which grants access to the
     * ingestion and DLQ locations of a single datastore based measurement.
     */
    public static getRoleName({
        businessID,
        measurementId,
    }: Pick<DatastoreAccessInformation, 'businessID' | 'measurementId'>) {
        return `datastore-${businessID}-${measurementId}`;
    }

    /**
     * The prefix within the ingestion and DLQ buckets which belongs to a single business.
     */
    public static getPrefix(businessID: string) {
        return `${businessID}`;
    }

    public static getIngestionLocation(businessID: string) {
        if (!businessID) {
            return undefined;
        }
        return `s3://${process.env.DB_MEASUREMENT_BUCKET_NAME}/${DatastoreAccessInformation.getPrefix(businessID)}`;
    }

    public static getDLQLocation(businessID: string) {
        if (!businessID) {
            return undefined;
        }
        return `s3://${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${DatastoreAccessInformation.getPrefix(businessID)}`;
    }

    /**
     * The trust policy of the generated IAM role.
     * Only the account which owns the datastore can assume the role, and only when it presents the external ID.
     */
    public static getTrustPolicy({ accountId, externalId }: { accountId: string; externalId: string }) {
        return {
            Version: '2012-10-17',
            Statement: [
                {
                    Effect: 'Allow',
                    Principal: {
                        AWS: `arn:aws:iam::${accountId}:root`,
                    },
                    Action: 'sts:AssumeRole',
                    Condition: {
                        StringEquals: {
                            'sts:ExternalId': externalId,
                        },
                    },
                },
            ],
        };
    }

    /**
     * The access policy of the generated IAM role.
     * Access is scoped down to the ingestion and DLQ prefixes belonging to the business.
     */
    public static getAccessPolicy(businessID: string) {
        const prefix = DatastoreAccessInformation.getPrefix(businessID);
        return {
            Version: '2012-10-17',
            Statement: [
                {
                    Sid: 'IngestionAccess',
                    Effect: 'Allow',
                    Action: ['s3:GetObject', 's3:PutObject'],
                    Resource: [`arn:aws:s3:::${process.env.DB_MEASUREMENT_BUCKET_NAME}/${prefix}/*`],
                },
                {
                    Sid: 'DLQAccess',
                    Effect: 'Allow',
                    // Only need read on the DLQ, enterprise is the only producer of failed records
                    Action: ['s3:GetObject'],
                    Resource: [`arn:aws:s3:::${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${prefix}/*`],
                },
            ],
        };
    }

    public static transformer(datastoreAccessInformation: DatastoreAccessInformation, influxPoint: Point) {
        if (datastoreAccessInformation) {
            const { platform, accountId, region, iamRoleArn, externalId, ingestion, dlq } =
                datastoreAccessInformation;
            if (platform) influxPoint.tag('platform', platform);
            if (accountId) influxPoint.tag('accountId', accountId);
            if (region) influxPoint.tag('region', region);
            if (iamRoleArn) influxPoint.tag('iamRoleArn', iamRoleArn);
            if (externalId) influxPoint.tag('externalId', externalId);
            if (ingestion) influxPoint.tag('ingestion', ingestion);
            if (dlq) influxPoint.tag('dlq', dlq);
        }
        return influxPoint;
    }

    public static dbModelToEntity({
        platform,
        accountId,
        region,
        iamRoleArn,
        externalId,
        ingestion,
        dlq,
        businessID,
        measurementId,
        ...rest
    }: {
        [x: string]: any;
    }) {
        return new DatastoreAccessInformation({
            platform,
            accountId: accountId ? accountId : rest?.cloudId,
            region,
            iamRoleArn,
            externalId,
            ingestion,
            dlq,
            businessID,
            measurementId,
        } as DatastoreAccessInformation);
    }

    /**
     * Provisions the access needed for a datastore based measurement.
     *
     * A dedicated IAM role, uniquely named after the business and the measurement, is created.
     * The role is only assumable by the account which owns the datastore, and only when a freshly
     * generated external ID is presented. The policy attached to the role scopes access down to the
     * ingestion and DLQ prefixes belonging to the business.
     *
     * The generated access information is set on the passed in configuration, and returned, so it can
     * be returned to, and persisted for, the business.
     */
    public static async setupAccess(dbAccessInformation: DatastoreAccessInformation) {
        if (!dbAccessInformation) {
            return dbAccessInformation;
        }
        const { accountId, businessID, measurementId } = dbAccessInformation;
        const platform = dbAccessInformation.platform ? dbAccessInformation.platform : SupportedDatastores.s3;
        if (platform !== SupportedDatastores.s3) {
            return dbAccessInformation;
        }
        if (!accountId) {
            throw new BadRequestException('An accountId is required for datastore based measurements');
        }
        const roleName = DatastoreAccessInformation.getRoleName({ businessID, measurementId });
        const externalId = dbAccessInformation.externalId ? dbAccessInformation.externalId : randomUUID();
        const trustPolicy = DatastoreAccessInformation.getTrustPolicy({ accountId, externalId });
        const accessPolicy = DatastoreAccessInformation.getAccessPolicy(businessID);
        const iam = DatastoreAccessInformation.getIAMClient();
        try {
            const createdRole = await iam.createRole({
                RoleName: roleName,
                Description: `Enterprise datastore based usage ingestion for businessID: ${businessID} measurementId: ${measurementId}`,
                AssumeRolePolicyDocument: JSON.stringify(trustPolicy),
                Tags: [
                    { Key: 'businessID', Value: `${businessID}` },
                    { Key: 'measurementId', Value: `${measurementId}` },
                ],
            });
            await DatastoreAccessInformation.attachAccessPolicy(iam, roleName, accessPolicy);

            dbAccessInformation.platform = platform;
            dbAccessInformation.externalId = externalId;
            dbAccessInformation.iamRoleArn = createdRole?.Role?.Arn
                ? createdRole.Role.Arn
                : `arn:aws:iam::${process.env.ENTERPRISE_AWS_ACCOUNT_ID ?? ''}:role/${roleName}`;
            dbAccessInformation.region = dbAccessInformation.region
                ? dbAccessInformation.region
                : DatastoreAccessInformation.defaultRegion;
            dbAccessInformation.ingestion = DatastoreAccessInformation.getIngestionLocation(businessID);
            dbAccessInformation.dlq = DatastoreAccessInformation.getDLQLocation(businessID);

            return dbAccessInformation;
        } catch (e) {
            throw DatastoreAccessInformation.normalizeError(e, accountId);
        }
    }

    /**
     * Updates the access of an already provisioned datastore based measurement.
     *
     * Only the trust of the role changes, the role itself and the external ID which has already been
     * handed out to the business are preserved.
     */
    public static async updateAccess(dbAccessInformation: DatastoreAccessInformation) {
        if (!dbAccessInformation) {
            return dbAccessInformation;
        }
        const { accountId, businessID, measurementId, iamRoleArn, externalId } = dbAccessInformation;
        const platform = dbAccessInformation.platform ? dbAccessInformation.platform : SupportedDatastores.s3;
        if (platform !== SupportedDatastores.s3) {
            return dbAccessInformation;
        }
        if (!accountId) {
            throw new BadRequestException('An accountId is required for datastore based measurements');
        }
        if (!iamRoleArn || !externalId) {
            // Nothing has been provisioned for this measurement yet
            return DatastoreAccessInformation.setupAccess(dbAccessInformation);
        }
        const roleName = DatastoreAccessInformation.getRoleNameFromArn(iamRoleArn)
            ? DatastoreAccessInformation.getRoleNameFromArn(iamRoleArn)
            : DatastoreAccessInformation.getRoleName({ businessID, measurementId });
        const iam = DatastoreAccessInformation.getIAMClient();
        try {
            await iam.updateAssumeRolePolicy({
                RoleName: roleName,
                PolicyDocument: JSON.stringify(
                    DatastoreAccessInformation.getTrustPolicy({ accountId, externalId })
                ),
            });
        } catch (e) {
            throw DatastoreAccessInformation.normalizeError(e, accountId);
        }
        dbAccessInformation.platform = platform;
        dbAccessInformation.iamRoleArn = iamRoleArn;
        dbAccessInformation.externalId = externalId;
        dbAccessInformation.region = dbAccessInformation.region
            ? dbAccessInformation.region
            : DatastoreAccessInformation.defaultRegion;
        dbAccessInformation.ingestion = DatastoreAccessInformation.getIngestionLocation(businessID);
        dbAccessInformation.dlq = DatastoreAccessInformation.getDLQLocation(businessID);
        return dbAccessInformation;
    }

    public static getRoleNameFromArn(iamRoleArn: string) {
        if (!iamRoleArn) {
            return undefined;
        }
        const [, roleName] = iamRoleArn.split(':role/');
        return roleName ? roleName : undefined;
    }

    private static getIAMClient() {
        return new IAM({ region: process.env.AWS_REGION ? process.env.AWS_REGION : DatastoreAccessInformation.defaultRegion });
    }

    /**
     * Grants the generated role access to the ingestion and DLQ prefixes of the business.
     * A managed policy, named after the role, is preferred. When the ARN of the managed policy cannot be
     * determined the same document is attached inline to the role instead.
     */
    private static async attachAccessPolicy(iam: IAM, roleName: string, accessPolicy: Record<string, unknown>) {
        const PolicyDocument = JSON.stringify(accessPolicy);
        let policyArn: string;
        try {
            const createdPolicy = await iam.createPolicy({
                PolicyName: roleName,
                Description: `Enterprise datastore based usage ingestion access for role: ${roleName}`,
                PolicyDocument,
            });
            policyArn = createdPolicy?.Policy?.Arn;
        } catch (e) {
            DatastoreAccessInformation.logger.warn(
                `Unable to create a managed policy for role ${roleName}, falling back to an inline policy`,
                e
            );
        }
        if (policyArn) {
            await iam.attachRolePolicy({ RoleName: roleName, PolicyArn: policyArn });
        } else {
            await iam.putRolePolicy({ RoleName: roleName, PolicyName: roleName, PolicyDocument });
        }
    }

    private static normalizeError(e, accountId: string) {
        const code = e?.Code ? e.Code : e?.name;
        if (code && `${code}`.startsWith('MalformedPolicy')) {
            return new BadRequestException(`AccountId: ${accountId} is invalid`);
        }
        return e;
    }
}

