import { CreateUsageDto } from './create-usage.dto';

/**
 * The payload delivered by the internal datastore based connectors.
 */
export class DbMeasuredusageDto {
    /**
     * A single standard usage record, as delivered by the connector.
     * The connector delivers the record as the raw JSON string it read from the datastore.
     */
    message: CreateUsageDto | string;

    /**
     * The key of the object in the ingestion datastore the record was read from.
     * The first segment of the key is the businessID which produced the record.
     */
