}

import {
    AttachRolePolicyCommand,
    CreatePolicyCommand,
    CreateRoleCommand,
    IAM,
    PutRolePolicyCommand,
    UpdateAssumeRolePolicyCommand,
} from '@aws-sdk/client-iam';
import { PutObjectCommand, S3 } from '@aws-sdk/client-s3';
import { mockClient } from 'aws-sdk-client-mock';
import { measurementMode } from '../dto/create-measurement-config.dto';
import { DatastoreAccessInformation, MeasurementConfigEntity, SupportedDatastores } from './measurement-config.entity';
import { StandardMeasurementEntity } from './standardMeasurement.entity';

const iamMock = mockClient(IAM);
const s3Mock = mockClient(S3);

const businessID = 'fakeBusiness';
const measurementId = 'fakeMeasurementId';
const accountId = '623673123435';

describe('DatastoreAccessInformation', () => {
    beforeAll(() => {
        process.env.DB_MEASUREMENT_BUCKET_NAME = 'enterprise-usage-record-dump-bucket';
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'enterprise-usage-record-dlq-bucket';
    });

    beforeEach(() => {
        iamMock.reset();
        s3Mock.reset();
        iamMock.on(CreateRoleCommand).resolves({
            Role: {
                RoleName: `datastore-${businessID}-${measurementId}`,
                Arn: `arn:aws:iam::647662420899:role/datastore-${businessID}-${measurementId}`,
            },
        } as never);
    });

    it('defaults the platform and the region', () => {
        const configuration = new DatastoreAccessInformation({ accountId } as DatastoreAccessInformation);

        expect(configuration.platform).toEqual(SupportedDatastores.s3);
        expect(configuration.region).toEqual('us-east-1');
        expect(configuration.accountId).toEqual(accountId);
    });

    it('provisions a uniquely named role, trusting the customer account with a fresh external ID', async () => {
        const configuration = new DatastoreAccessInformation({
            platform: SupportedDatastores.s3,
            accountId,
            businessID,
            measurementId,
        } as DatastoreAccessInformation);

        const result = await DatastoreAccessInformation.setupAccess(configuration);

        const [createRole] = iamMock.commandCalls(CreateRoleCommand);
        expect(createRole.args[0].input.RoleName).toEqual(`datastore-${businessID}-${measurementId}`);
        const trustPolicy = JSON.parse(createRole.args[0].input.AssumeRolePolicyDocument);
        expect(trustPolicy.Statement[0].Principal.AWS).toEqual(`arn:aws:iam::${accountId}:root`);
        expect(trustPolicy.Statement[0].Condition.StringEquals['sts:ExternalId']).toEqual(result.externalId);
        expect(result.externalId).toBeTruthy();
        expect(result.iamRoleArn).toEqual(`arn:aws:iam::647662420899:role/datastore-${businessID}-${measurementId}`);
        expect(result.ingestion).toEqual(`s3://${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}`);
        expect(result.dlq).toEqual(`s3://${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}`);
        expect(result.region).toEqual('us-east-1');
    });

    it('scopes the policy of the role down to the ingestion and DLQ prefixes of the business', async () => {
        const configuration = new DatastoreAccessInformation({
            accountId,
            businessID,
            measurementId,
        } as DatastoreAccessInformation);

        await DatastoreAccessInformation.setupAccess(configuration);

        // No managed policy ARN could be determined so the document is attached inline
        const [putRolePolicy] = iamMock.commandCalls(PutRolePolicyCommand);
        const policy = JSON.parse(putRolePolicy.args[0].input.PolicyDocument);
        expect(putRolePolicy.args[0].input.RoleName).toEqual(`datastore-${businessID}-${measurementId}`);
        expect(policy.Statement[0].Resource).toEqual([
            `arn:aws:s3:::${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}/*`,
        ]);
        expect(policy.Statement[1].Resource).toEqual([
            `arn:aws:s3:::${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}/*`,
        ]);
    });

    it('attaches the managed policy when one could be created', async () => {
        iamMock.on(CreatePolicyCommand).resolves({
            Policy: { Arn: `arn:aws:iam::647662420899:policy/datastore-${businessID}-${measurementId}` },
        } as never);
        const configuration = new DatastoreAccessInformation({
            accountId,
            businessID,
            measurementId,
        } as DatastoreAccessInformation);

        await DatastoreAccessInformation.setupAccess(configuration);

        const [attachRolePolicy] = iamMock.commandCalls(AttachRolePolicyCommand);
        expect(attachRolePolicy.args[0].input.PolicyArn).toEqual(
            `arn:aws:iam::647662420899:policy/datastore-${businessID}-${measurementId}`
        );
        expect(iamMock.commandCalls(PutRolePolicyCommand).length).toEqual(0);
    });

    it('updates the trust of the role while preserving the role and the external ID', async () => {
        const configuration = new DatastoreAccessInformation({
            accountId: '999999999999',
            businessID,
            measurementId,
            iamRoleArn: `arn:aws:iam::647662420899:role/datastore-${businessID}-${measurementId}`,
            externalId: 'existing-external-id',
        } as DatastoreAccessInformation);

        const result = await DatastoreAccessInformation.updateAccess(configuration);

        const [updateTrust] = iamMock.commandCalls(UpdateAssumeRolePolicyCommand);
        expect(updateTrust.args[0].input.RoleName).toEqual(`datastore-${businessID}-${measurementId}`);
        const trustPolicy = JSON.parse(updateTrust.args[0].input.PolicyDocument);
        expect(trustPolicy.Statement[0].Principal.AWS).toEqual(`arn:aws:iam::999999999999:root`);
        expect(trustPolicy.Statement[0].Condition.StringEquals['sts:ExternalId']).toEqual('existing-external-id');
        expect(result.externalId).toEqual('existing-external-id');
        expect(result.iamRoleArn).toEqual(`arn:aws:iam::647662420899:role/datastore-${businessID}-${measurementId}`);
        expect(iamMock.commandCalls(CreateRoleCommand).length).toEqual(0);
    });

    it('persists and reads back the generated access information', async () => {
        const entity = new MeasurementConfigEntity({
            measurementId,
            businessID,
            measurementMode: measurementMode.datastoreBased,
            measurementConfiguration: { accountId } as DatastoreAccessInformation,
        } as MeasurementConfigEntity);
        await MeasurementConfigEntity.setupAccessIfRequired(entity);
        const tags: Record<string, string> = {};
        const influxService: any = {
            getPoint: () => ({
                tag: (key: string, value: string) => {
                    tags[key] = value;
                },
                stringField: () => undefined,
            }),
        };

        MeasurementConfigEntity.transformer(entity, influxService);

        const configuration = entity.measurementConfiguration as DatastoreAccessInformation;
        expect(tags.accountId).toEqual(accountId);
        expect(tags.platform).toEqual(SupportedDatastores.s3);
        expect(tags.region).toEqual('us-east-1');
        expect(tags.iamRoleArn).toEqual(configuration.iamRoleArn);
        expect(tags.externalId).toEqual(configuration.externalId);
        expect(tags.ingestion).toEqual(configuration.ingestion);
        expect(tags.dlq).toEqual(configuration.dlq);

        const readBack = MeasurementConfigEntity.dbModelToEntity({
            ...tags,
            _value: measurementMode.datastoreBased,
            measurementId,
            businessID,
        });
        expect(readBack.measurementConfiguration).toEqual(configuration);
    });
});

describe('StandardMeasurementEntity.publishFailureToDLQ', () => {
    beforeAll(() => {
        process.env.DB_MEASUREMENT_BUCKET_NAME = 'enterprise-usage-record-dump-bucket';
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'enterprise-usage-record-dlq-bucket';
    });

    beforeEach(() => {
        s3Mock.reset();
    });

    it('mirrors the source key of the failed record in the DLQ', async () => {
        await StandardMeasurementEntity.publishFailureToDLQ({
            input: { message: 'not json', s3Key: `${businessID}/2023/02/record.json` },
            s3Key: `${businessID}/2023/02/record.json`,
            error: new Error('Unexpected token'),
        });

        const [putObject] = s3Mock.commandCalls(PutObjectCommand);
        expect(putObject.args[0].input.Bucket).toEqual(process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME);
        expect(putObject.args[0].input.Key).toEqual(`${businessID}/2023/02/record.json.message.text`);
        const body = JSON.parse(`${putObject.args[0].input.Body}`);
        expect(body.input).toEqual({ message: 'not json', s3Key: `${businessID}/2023/02/record.json` });
        expect(body.error).toEqual('Unexpected token');
        expect(body.timeStamp).toBeTruthy();
    });

    it('makes fully qualified source keys relative', async () => {
        await StandardMeasurementEntity.publishFailureToDLQ({
            input: 'nonsense',
            s3Key: `s3://${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}/record.json`,
        });

        const [putObject] = s3Mock.commandCalls(PutObjectCommand);
        expect(putObject.args[0].input.Key).toEqual(`${businessID}/record.json.message.text`);
    });
});

