import { Logger } from '@nestjs/common';

const logger = new Logger('AwsSdk');

/**
 * The logger handed to the AWS SDK clients so that anything the SDK has to say about a request ends up
 * in the application logs. The chatty levels are dropped, only warnings and errors are surfaced.
 */
export const awsSdkLogger = {
    trace: () => undefined,
    debug: () => undefined,
    info: () => undefined,
    warn: (...content: any[]) => logger.warn(content),
    error: (...content: any[]) => logger.error(content),
};

/**
 * Builds a client for an AWS service. The aggregated client of a service, when the SDK ships one, is
 * preferred over the command only client.
 */
export const getAwsClient = <TClient>(clients: any[], config: any = {}): TClient => {
    const Client = clients.find((candidate) => typeof candidate === 'function');
    if (!Client) {
        throw new Error('No AWS client available for the requested service');
    }
    return new Client({ logger: awsSdkLogger, ...config });
};

/**
 * The AWS SDK v3 exposes every operation of a service twice, as a method on the aggregated client,
 * `iam.createRole(input)`, and as a command sent through the client, `iam.send(new CreateRoleCommand(input))`.
 * Both flavours send the very same request.
 *
 * This sends an operation through whichever of the two flavours the client at hand exposes, so callers
 * don't have to care which one of the two they were handed.
 */
export const sendAwsOperation = async <TInput, TOutput>(
    client: any,
    operation: string,
    Command: new (input: TInput) => any,
    input: TInput
): Promise<TOutput> => {
    if (client && typeof client[operation] === 'function') {
        return client[operation](input);
    }
    return client.send(new Command(input));
};

