        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'enterprise-usage-record-dlq-bucket';
    });

    beforeEach(() => {
        s3Mock.reset();
        mockCreate.mockReset();
        mockCreate.mockResolvedValue({ message: 'Measurement created' });
        controller = new PrivateAPIUsageController({ create: mockCreate } as unknown as UsageService);
    });

    it('sends a valid record through the usage service with the businessID from the s3Key', async () => {
        const record = {
            timeStamp: '2023-02-08T19:24:10Z',
            dimensionId: 'da9611bd-e0f3-4c0d-a754-fda5be730872',
            recordValue: '0.87',
        };

        const response = await controller.dbUsage({
            message: JSON.stringify(record),
            s3Key: 'fakeBusiness/2023/02/08/record.json',
        });

        expect(mockCreate).toHaveBeenCalledWith({ ...record, businessID: 'fakeBusiness' });
        expect(response).toEqual({ message: 'Measurement created' });
        expect(s3Mock.commandCalls(PutObjectCommand).length).toEqual(0);
    });

    it('publishes malformed records to the DLQ under the mirrored source key', async () => {
        const failedInput = { message: '{"recordValue": ', s3Key: 'fakeBusiness/2023/02/08/record.json' };

        await controller.dbUsage(failedInput);

        expect(mockCreate).not.toHaveBeenCalled();
        const [putObject] = s3Mock.commandCalls(PutObjectCommand);
        expect(putObject.args[0].input.Bucket).toEqual(process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME);
        expect(putObject.args[0].input.Key).toEqual('fakeBusiness/2023/02/08/record.json.message.text');
        const body = JSON.parse(`${putObject.args[0].input.Body}`);
        expect(body.input).toEqual(failedInput);
        expect(body.error).toBeTruthy();
    });

    it('publishes records without an s3Key to the DLQ', async () => {
        await controller.dbUsage({ message: JSON.stringify({ recordValue: '1' }) });

        expect(mockCreate).not.toHaveBeenCalled();
        expect(s3Mock.commandCalls(PutObjectCommand).length).toEqual(1);
    });
});

