import { CreateRoleCommand, IAM } from '@aws-sdk/client-iam';
import { Test, TestingModule } from '@nestjs/testing';
import { mockClient } from 'aws-sdk-client-mock';
import { DimensionsService } from '../dimensions/dimensions.service';
import { InfluxService } from '../influx/influx.service';
import { SchedulerService } from '../scheduler/scheduler.service';
import { measurementMode } from './dto/create-measurement-config.dto';
import { DatastoreAccessInformation, SupportedDatastores } from './entities/measurement-config.entity';
import { MeasurementConfigService } from './measurement-config.service';

const iamMock = mockClient(IAM);

const businessID = 'fakeBusiness';
const accountId = '623673123435';

describe('MeasurementConfigService datastore based measurements', () => {
    let service: MeasurementConfigService;
    const mockLoadPoints = jest.fn();
    const mockReadMeasurementConfigData = jest.fn();

    beforeAll(() => {
        process.env.DB_MEASUREMENT_BUCKET_NAME = 'enterprise-usage-record-dump-bucket';
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'enterprise-usage-record-dlq-bucket';
    });

    beforeEach(async () => {
        iamMock.reset();
        mockLoadPoints.mockReset();
        mockReadMeasurementConfigData.mockReset();
        const module: TestingModule = await Test.createTestingModule({
            providers: [MeasurementConfigService],
            imports: [],
        })
            .useMocker((token) => {
                if (token === InfluxService) {
                    return {
                        loadPoints: mockLoadPoints,
                        getPoint: () => ({ tag: jest.fn(), stringField: jest.fn() }),
                        readMeasurementConfigData: mockReadMeasurementConfigData,
                    };
                }
                if (token === SchedulerService) {
                    return { create: jest.fn() };
                }
                if (token === DimensionsService) {
                    return { transformDtoToEntityInput: jest.fn(), findOneByDimensionId: jest.fn() };
                }
            })
            .compile();
        service = module.get<MeasurementConfigService>(MeasurementConfigService);
    });

    it('provisions access and returns the generated configuration when creating a measurement', async () => {
        const response = await service.create(
            {
                businessID,
                measurementMode: measurementMode.datastoreBased,
                measurementConfiguration: { accountId } as DatastoreAccessInformation,
            },
            'fakeSubject'
        );

        const configuration = response.measurementConfiguration as DatastoreAccessInformation;
        const [createRole] = iamMock.commandCalls(CreateRoleCommand);
        expect(createRole.args[0].input.RoleName).toEqual(`datastore-${businessID}-${response.measurementId}`);
        expect(configuration.platform).toEqual(SupportedDatastores.s3);
        expect(configuration.accountId).toEqual(accountId);
        expect(configuration.region).toEqual('us-east-1');
        expect(configuration.externalId).toBeTruthy();
        expect(configuration.iamRoleArn).toContain(`datastore-${businessID}-${response.measurementId}`);
        expect(configuration.ingestion).toEqual(`s3://${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}`);
        expect(configuration.dlq).toEqual(`s3://${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}`);
        expect(mockLoadPoints).toHaveBeenCalled();
    });

    it('leaves the access of other measurement modes alone', async () => {
        const response = await service.create(
            {
                businessID,
                measurementMode: measurementMode.agentBased,
                measurementConfiguration: {
                    iamRoleArn: 'arn:aws:iam::214826386939:role/enterprise-scraper',
                    externalId: 'fakeExternalId',
                    hostingPlatform: undefined,
                },
            },
            'fakeSubject'
        );

        expect(response).toEqual({ message: 'Created Measurement Configuration', measurementId: response.measurementId });
        expect(iamMock.calls().length).toEqual(0);
    });
});

