+    /**
+     * Takes the key of a record in the datastore it was consumed from, and returns the key it is
+     * mirrored to in the DLQ. Fully qualified locations, `s3://bucket/key`, are made relative,
+     * keys which are already relative are passed through untouched.
+     */
+    static getDLQKey(sourceKey: string) {
+        if (!sourceKey) {
+            return undefined;
+        }
+        let relativeKey = `${sourceKey}`.replace(/^s3:\/\/[^/]+\//, '').replace(/^arn:aws:s3:::[^/]+\//, '');
+        const ingestionBucket = process.env.DB_MEASUREMENT_BUCKET_NAME;
+        if (ingestionBucket && relativeKey.startsWith(`${ingestionBucket}/`)) {
+            relativeKey = relativeKey.slice(`${ingestionBucket}/`.length);
+        }
+        relativeKey = relativeKey.replace(/^\/+/, '');
+        return `${relativeKey}${StandardMeasurementEntity.dlqKeySuffix}`;
+    }
+
+    /**
