+     */
+    static async publishFailureToDLQ(failure: FailedMeasurementDelivery | any, sourceKeyOverride?: string) {
+        const sourceKey = sourceKeyOverride
+            ? sourceKeyOverride
+            : failure?.s3Key
+            ? failure.s3Key
+            : failure?.sourceKey
+            ? failure.sourceKey
+            : failure?.key;
+        const bucket = failure?.bucket ? failure.bucket : process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME;
+        // Without a source key there is nothing to mirror, the failure is still kept for manual processing
+        const key = sourceKey
+            ? StandardMeasurementEntity.getDLQKey(sourceKey)
+            : `unattributed/${randomUUID()}${StandardMeasurementEntity.dlqKeySuffix}`;
+        const error = failure?.error;
+        const body = {
+            error: error instanceof Error ? error.message : error,
+            input: failure?.input !== undefined ? failure.input : failure,
+            message: failure?.message,
+            s3Key: sourceKey,
+            key,
+            bucket,
+            timeStamp: new Date().toISOString(),
+        };
+        StandardMeasurementEntity.logger.warn(`Publishing failed usage record to the DLQ: ${bucket}/${key}`);
+        const s3 = getAwsClient<S3 | S3Client>([S3, S3Client], {
+            region: process.env.AWS_REGION ? process.env.AWS_REGION : 'us-east-1',
+        });
+        try {
+            await sendAwsOperation<PutObjectCommandInput, PutObjectCommandOutput>(s3, 'putObject', PutObjectCommand, {
+                Bucket: bucket,
+                Key: key,
+                Body: JSON.stringify(body),
+                ContentType: 'text/plain',
+            });
+        } catch (err) {
+            AuditService.publishEvent({
+                data: [{ err }],
+                message: 'Failed to publish failed usage record to the DLQ',
+                topic: AuditScope.ERROR,
+            });
+            throw err;
+        }
+        return { message: 'Published failed usage record to the DLQ', bucket, key };
+    }
 }
